        { static const uint64_t a[] = {0x20000024ull}; static const uint32_t m[] = {0xffffffffu}; ck_call(1, 0x4c2dfbu, 0x5cf659ull, 1, a, m); }
        { static const uint64_t a[] = {0x1ull}; static const uint32_t m[] = {0xffffu}; ck_call(2, 0x4d3992u, 0x0ull, 1, a, m); }
        { static const uint64_t a[] = {0}; static const uint32_t m[] = {0}; ck_call(3, 0x48217au, 0x20000000ull, 0, a, m); }
        ck_blk(b_self, 40, 14, ov_self, 10, pt_self, 0);
